async function inspect_analysis() {
  // Get the entry-to-exit map for submit
  const map = await tools.semantic_query({
    analysis: "SHOP/payments",
    operation: "flowmap",
    from: { name: "submit" },
    all: true
  });

  // Find the edge where rebate parameter flows to save's argument 1
  let targetEdge = null;
  for (const edge of map.flowMap.edges) {
    if (edge.from.name === "submit" && edge.to.name === "save") {
      // Check if this edge involves the rebate parameter
      const fromSide = edge.sides.find(s => s.data?.parameter?.name === "rebate");
      const toSide = edge.sides.find(s => s.data?.argument?.index === 1);
      if (fromSide && toSide) {
        targetEdge = edge;
        break;
      }
    }
  }

  if (!targetEdge) {
    text("No direct edge from submit.rebate to save.arg[1] found in flow map");
    return null;
  }

  // Get the trace for this specific path with assumption rebate < 0 is false
  const trace = await tools.semantic_trace({
    analysis: "SHOP/payments",
    from: { kind: "method", name: "submit", parameter: "rebate" },
    to: { kind: "call", name: "save", argument: 1 },
    assumptions: [{ expression: "rebate < 0", holds: false }],
    all: true
  });

  // Extract required fields
  const entry = targetEdge.from.name;
  const exitCall = targetEdge.to.name;
  const sinkExpression = trace.sides.find(s => s.data?.argument?.index === 1)?.data?.expression || "save.arg[1]";

  // Get assumption evaluation statuses from the trace
  const controlAssumption = trace.assumptions.find(a => a.expression.includes("rebate < 0"))?.status;
  const dataAssumption = trace.sides.find(s => s.data?.parameter?.name === "rebate")?.assumptionEvaluation?.status;

  // Check if map is complete
  const mapComplete = map.flowMap.complete;

  // Get evidence view links (these would be in the full response)
  const evidenceViews = [];
  if (map.flowMap.evidenceLinks) {
    evidenceViews.push(...map.flowMap.evidenceLinks);
  }

  return {
    entry,
    exitCall,
    sinkExpression,
    controlAssumption: controlAssumption || "not found",
    dataAssumption: dataAssumption || "not found",
    behaviorVerified: trace.assumptions.some(a => a.status === "verified"),
    mapComplete,
    evidenceViews
  };
}

inspect_analysis().then(result => {
  text(JSON.stringify(result, null, 2));
